#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-source-coverage.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * verify-source-coverage — refuses .ts/.tsx files in src/ that aren't
 * EXPLICITLY listed in some __specs__/spec.yaml's `owns:` field.
 * Every source file resolves to either a spec.yaml `owns:` entry or an
 * `.ignore.specs.yaml` exemption marker; nothing slips through unowned.
 *
 * Tier note: a COMPONENT-tier spec.yaml (COMPONENT_CREATION.yaml.component_spec_schema)
 * uses `component:` + `folder:` instead of feature_name/owns. Such a component folder
 * owns every source file beneath it by construction — no explicit owns: list needed.
 *
 * Algorithm:
 *   1. Walk src/ once. For every __specs__/spec.yaml, parse feature_name
 *      + owns list. Build an index: { feature_name → { specPath, owns: Set<repo-relative-path> } }.
 *      feature_name MUST be unique repo-wide — duplicates are violations.
 *   2. Walk src/ again to find every .ts/.tsx file (excluding
 *      __tests__/ + test files + generated files).
 *   3. For each file: walk up parent dirs to src/. Look for
 *      __specs__/spec.yaml OR .ignore.specs.yaml whichever comes first.
 *      - Found __specs__/spec.yaml: the file's repo-relative path MUST
 *        appear in that spec.yaml's owns: list. Violation otherwise.
 *      - Found .ignore.specs.yaml empty: file is exempt.
 *      - Found .ignore.specs.yaml with feature_name: X: look up X in
 *        the feature index. The file's repo-relative path MUST appear
 *        in X's owns: list. Violation otherwise.
 *      - Reached src/ with no marker: NAKED violation.
 *
 * Usage:
 *   node scripts/verify/verify-source-coverage.mjs [<source-root>]
 *
 * Exits 0 when every file resolves; non-zero on any violation.
 */
import { readdir, readFile } from "node:fs/promises";
import { join, relative, dirname } from "node:path";
import { existsSync } from "node:fs";

const SOURCE_ROOT = process.argv[2] || "src";
const REPO_ROOT = process.cwd();
const absRoot = join(REPO_ROOT, SOURCE_ROOT);

const IGNORE_DIRS = new Set([
  "node_modules",
  ".next",
  ".turbo",
  "coverage",
  "test-results",
  "playwright-report",
  ".git",
  "dist",
  "build",
  "out",
]);

const SOURCE_EXTS = [".ts", ".tsx"];

if (!existsSync(absRoot)) {
  process.stderr.write(
    `\n❌ verify-source-coverage: source root '${SOURCE_ROOT}' not found at ${absRoot}\n`,
  );
  process.exit(2);
}

// ---------- pass 1: enumerate every feature_name + owns list ----------

const featuresIndex = new Map(); // feature_name -> { specPath, owns: Set<string> }
const featureDeclarations = new Map(); // feature_name -> [specPath, ...] (duplicate detection)
await collectFeatures(absRoot);

async function collectFeatures(dir) {
  let entries;
  try {
    entries = await readdir(dir, { withFileTypes: true });
  } catch {
    return;
  }
  const specsDir = entries.find((e) => e.isDirectory() && e.name === "__specs__");
  if (specsDir) {
    const specPath = join(dir, "__specs__", "spec.yaml");
    if (existsSync(specPath)) {
      const text = await readFile(specPath, "utf-8");
      const name = grabField(text, "feature_name");
      const owns = grabListField(text, "owns");
      if (name) {
        featuresIndex.set(name, {
          specPath: relative(REPO_ROOT, specPath),
          owns: new Set(owns),
        });
        const declared = featureDeclarations.get(name) ?? [];
        declared.push(relative(REPO_ROOT, specPath));
        featureDeclarations.set(name, declared);
      }
    }
  }
  for (const e of entries) {
    if (!e.isDirectory()) continue;
    if (IGNORE_DIRS.has(e.name)) continue;
    if (e.name === "__specs__" || e.name === "__tests__") continue;
    await collectFeatures(join(dir, e.name));
  }
}

// ---------- pass 2: walk every source file + resolve coverage ----------

const violations = [];
let covered = 0;
let exempt = 0;

// feature_name MUST be unique repo-wide — two spec.yaml files declaring the
// same feature_name make ownership resolution ambiguous.
for (const [name, paths] of featureDeclarations) {
  if (paths.length > 1) {
    violations.push(
      `DUPLICATE feature_name="${name}" — declared at ${paths.join(" AND ")}. feature_name MUST be unique repo-wide.`,
    );
  }
}

await walkSources(absRoot);

async function walkSources(dir) {
  let entries;
  try {
    entries = await readdir(dir, { withFileTypes: true });
  } catch {
    return;
  }
  for (const e of entries) {
    if (e.isDirectory()) {
      if (IGNORE_DIRS.has(e.name)) continue;
      if (e.name === "__tests__") continue;
      await walkSources(join(dir, e.name));
      continue;
    }
    if (!e.isFile()) continue;
    if (!SOURCE_EXTS.some((ext) => e.name.endsWith(ext))) continue;
    if (e.name.endsWith(".test.ts") || e.name.endsWith(".test.tsx")) continue;
    if (e.name === "next-env.d.ts") continue;
    await auditSource(join(dir, e.name));
  }
}

async function auditSource(filePath) {
  const rel = relative(REPO_ROOT, filePath);
  let cur = dirname(filePath);
  while (true) {
    const specPath = join(cur, "__specs__", "spec.yaml");
    const ignorePath = join(cur, ".ignore.specs.yaml");

    if (existsSync(specPath)) {
      const text = await readFile(specPath, "utf-8");
      const name = grabField(text, "feature_name");
      const owns = new Set(grabListField(text, "owns"));
      if (!name) {
        // Component-tier spec (COMPONENT_CREATION.yaml.component_spec_schema) uses
        // `component:` + `folder:` instead of feature_name/owns — by design. Such a
        // component folder OWNS every source file beneath it by construction, so any
        // file under it is covered without an explicit owns: list.
        if (grabField(text, "component")) {
          covered++;
          return;
        }
        violations.push(
          `${rel}: parent ${relative(REPO_ROOT, specPath)} has no feature_name — cannot resolve ownership.`,
        );
        return;
      }
      if (!owns.has(rel)) {
        violations.push(
          `${rel}: under feature_name="${name}" (spec ${relative(REPO_ROOT, specPath)}) but NOT in that spec's owns: list. Add this path to owns: or move the file out of this feature.`,
        );
        return;
      }
      covered++;
      return;
    }

    if (existsSync(ignorePath)) {
      const text = (await readFile(ignorePath, "utf-8")).trim();
      if (text === "" || text.split("\n").every((l) => l.trim() === "" || l.trim().startsWith("#"))) {
        exempt++;
        return;
      }
      const declared = grabField(text, "feature_name");
      if (!declared) {
        violations.push(
          `${rel}: marker ${relative(REPO_ROOT, ignorePath)} has content + no feature_name — invalid marker.`,
        );
        return;
      }
      if (!featuresIndex.has(declared)) {
        violations.push(
          `${rel}: marker ${relative(REPO_ROOT, ignorePath)} names feature_name="${declared}" but no __specs__/spec.yaml declares it.`,
        );
        return;
      }
      const ownerInfo = featuresIndex.get(declared);
      if (!ownerInfo.owns.has(rel)) {
        violations.push(
          `${rel}: marker points at feature_name="${declared}" but that feature's spec (${ownerInfo.specPath}) owns: list does NOT include this file. Add it.`,
        );
        return;
      }
      covered++;
      return;
    }

    if (cur === absRoot) break;
    const parent = dirname(cur);
    if (parent === cur) break;
    cur = parent;
  }
  violations.push(
    `${rel}: NAKED — no __specs__/spec.yaml or .ignore.specs.yaml found in any parent up to ${SOURCE_ROOT}/.`,
  );
}

function grabField(contents, key) {
  const lines = contents
    .split("\n")
    .map((l) => l.replace(/\s*#.*$/, ""))
    .filter((l) => l.trim().length > 0);
  for (const line of lines) {
    const m = line.match(new RegExp(`^\\s*${key}\\s*:\\s*(.*)$`));
    if (m && m[1].trim() !== "") {
      return m[1].trim().replace(/^["']|["']$/g, "");
    }
  }
  return undefined;
}

function grabListField(contents, key) {
  const lines = contents.split("\n");
  const items = [];
  let inList = false;
  let listIndent = -1;
  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i];
    if (!inList) {
      const m = raw.match(new RegExp(`^(\\s*)${key}\\s*:\\s*$`));
      if (m) {
        inList = true;
        listIndent = m[1].length;
      }
      continue;
    }
    const trimmedRaw = raw.replace(/\s*#.*$/, "");
    if (trimmedRaw.trim() === "") continue;
    const indentMatch = trimmedRaw.match(/^(\s*)(.*)$/);
    const indent = indentMatch[1].length;
    const body = indentMatch[2];
    if (indent <= listIndent && !body.startsWith("- ")) {
      break;
    }
    if (body.startsWith("- ")) {
      const value = body.slice(2).trim().replace(/^["']|["']$/g, "");
      items.push(value);
    }
  }
  return items;
}

// ---------- output ----------

if (violations.length === 0) {
  process.stdout.write(
    `✅ verify-source-coverage — ${covered} file(s) covered + ${exempt} explicitly exempt; ${featuresIndex.size} feature(s) declared\n`,
  );
  process.exit(0);
}

process.stderr.write(
  `\n❌ verify-source-coverage: ${violations.length} violation(s)\n`,
);
for (const v of violations) process.stderr.write(`   - ${v}\n`);
process.stderr.write(
  `\n   ${covered} file(s) covered + ${exempt} exempt; ${featuresIndex.size} feature(s) declared.\n`,
);
process.exit(1);
